#!/usr/bin/env python3
"""Write the data behind the "Last Commit" badges on the PyPI projects page.

shields.io's own github/last-commit badge asks GitHub through a shared token
pool and fails often enough (about one request in eight in 2026-10) that the
21-row table at /portfolio/pypistats/ nearly always showed a grey
"last commit: invalid" somewhere. So the page uses shields' endpoint badge
instead: shields only draws it, and the date comes from a JSON file this
script writes, one per package, published on the `badges` branch by
.github/workflows/last-commit-badges.yml.

Message and colour follow shields' github/last-commit badge exactly
("today", "yesterday", "last friday", "october", "september 2025"; green when
fresh, red after two years), so the badges look the same as before.

The package list is the page itself: every `[gh-<package>]: https://github.com/<owner>/<repo>`
link in content/portfolio/pypistats/index.en.md gets a badge.

    GH_TOKEN=... python3 .github/scripts/gen_last_commit_badges.py --out badges

A repo GitHub fails to answer for keeps the file it already has in --out; the
run exits 1 only when a package has no file at all.
"""

import argparse
import json
import os
import re
import sys
import urllib.request
from datetime import datetime, timezone

REPO_ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..")
PAGE = os.path.join(REPO_ROOT, "content", "portfolio", "pypistats", "index.en.md")
REPO_LINK = re.compile(r"^\[gh-([a-z0-9-]+)\]: https://github\.com/([\w.-]+/[\w.-]+)$", re.M)

MONTHS = ("january", "february", "march", "april", "may", "june", "july",
          "august", "september", "october", "november", "december")
WEEKDAYS = ("monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday")
# shields' age(): days elapsed below each limit get that colour, older is red.
AGE_COLORS = ((7, "brightgreen"), (30, "green"), (180, "yellowgreen"), (365, "yellow"), (730, "orange"))

README = """# badges

Generated by `.github/workflows/last-commit-badges.yml` on `main`; do not edit.
One shields.io endpoint JSON per package on /portfolio/pypistats/, read by
`https://img.shields.io/endpoint?url=https://raw.githubusercontent.com/shenxianpeng/blog/badges/last-commit/<package>.json`.
"""


def packages(page_text):
    """{package: owner/repo} for every GitHub link on the page."""
    return dict(REPO_LINK.findall(page_text))


def format_date(commit, now):
    """shields' formatDate(): dayjs calendar() in UTC, current year dropped."""
    start_of_today = now.replace(hour=0, minute=0, second=0, microsecond=0)
    diff = (commit - start_of_today).total_seconds() / 86400
    if diff < -6:
        text = f"{MONTHS[commit.month - 1]} {commit.year}"
        return text.replace(f" {now.year}", "")
    if diff < -1:
        return f"last {WEEKDAYS[commit.weekday()]}"
    if diff < 0:
        return "yesterday"
    return "today"


def age_color(commit, now):
    days = (now - commit).days
    for limit, color in AGE_COLORS:
        if days < limit:
            return color
    return "red"


def badge(commit, now):
    return {
        "schemaVersion": 1,
        "label": "last commit",
        "message": format_date(commit, now),
        "color": age_color(commit, now),
    }


def last_commit(repo, token):
    """Author date of the newest commit on the default branch, like shields."""
    req = urllib.request.Request(
        f"https://api.github.com/repos/{repo}/commits?per_page=1",
        headers={"Accept": "application/vnd.github+json", "User-Agent": "shenxianpeng-blog-badges"},
    )
    if token:
        req.add_header("Authorization", f"Bearer {token}")
    with urllib.request.urlopen(req, timeout=30) as resp:
        date = json.load(resp)[0]["commit"]["author"]["date"]
    return datetime.fromisoformat(date.replace("Z", "+00:00"))


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    parser.add_argument("--out", required=True, help="checkout of the badges branch to update")
    parser.add_argument("--page", default=PAGE)
    args = parser.parse_args()

    with open(args.page, encoding="utf-8") as f:
        repos = packages(f.read())
    if not repos:
        sys.exit(f"no [gh-<package>] links found in {args.page}")

    token = os.environ.get("GH_TOKEN") or os.environ.get("GITHUB_TOKEN")
    now = datetime.now(timezone.utc)
    out_dir = os.path.join(args.out, "last-commit")
    os.makedirs(out_dir, exist_ok=True)

    missing = []
    for package, repo in sorted(repos.items()):
        path = os.path.join(out_dir, f"{package}.json")
        try:
            data = badge(last_commit(repo, token), now)
        except Exception as exc:  # keep yesterday's badge rather than none
            kept = os.path.exists(path)
            print(f"{package}: {repo}: {exc} ({'kept old file' if kept else 'NO FILE'})", file=sys.stderr)
            if not kept:
                missing.append(package)
            continue
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f)
            f.write("\n")
        print(f"{package}: {data['message']} ({data['color']})")

    for name in os.listdir(out_dir):
        if name.endswith(".json") and name[:-5] not in repos:
            os.remove(os.path.join(out_dir, name))
            print(f"{name[:-5]}: no longer on the page, removed")

    with open(os.path.join(args.out, "README.md"), "w", encoding="utf-8") as f:
        f.write(README)

    if missing:
        sys.exit(f"no badge for: {', '.join(missing)}")


if __name__ == "__main__":
    main()
